  Definition albase_regs : ltac2:(zQ "30!ig9!iie!iqa>4regs@2$2@1$0#5@1$1@1$0#k0>2pp@1$1@1$0#k0P") := ltac2:(zQ "b0!ig9!iie!lh8!kk8!pf!iqa!ln9!lhc!li4!lia!ki2\4regs@2$5@1$0#5@1$1@1$0#k0\2pp@1$1@1$0#k0@2$3@2$6^2^1@3$4@1$1@1$0#k0@2$7^2@3$8@1$0#5+h6Kv$2@2$9@1$0#5+h6@2$a@1$0#k0+muiop0").

  Ltac unset_v := repeat match goal with w := MV _ _ _ _ _ _ _ _ _ _ _ _ _ _ |- _ => subst w end.
  Ltac fin_reg HR' r :=
    unset_v; regv HR' r; cbn [edenot ev MENV mvals vals_ev nth app v_sp0 v_tid v_pp v_A v_len v_cap v_A2 v_n v_b8 v_b9 v_b10 v_b11 v_b0 v_b1];
