  Definition an_regs : ltac2:(zQ "40!ig9!kke!iie!iqa>4regs@2$3@1$0#5@1$2@1$0#k0>2pp@1$2@1$0#k0>1A$1>3len$1>3cap$1P") := ltac2:(zQ "c0!ig9!iie!lh8!kk8!pf!kke!lhc!li4!lia!ki2!iqa!lsc\4regs@2$a@1$0#5@1$1@1$0#k0\2pp@1$1@1$0#k0\1A$5\3len$5\3cap$5@2$3@2$b^5^4@2$3@3$4@1$1@1$0#k0@2$6^5@3$7@1$0#5+h3Kv$2@2$8@1$0#5+h3@2$9@1$0#k0^2@2$3@3$4@1$1@1$0#k0@2$6^5@3$7@1$0#5+h5Kv$2@2$8@1$0#5+h5@2$9@1$0#k0^1@3$4@1$1@1$0#k0@2$6^5@3$7@1$0#5+h7Kv$2@2$8@1$0#5+h7@2$9@1$0#k0^3").

  Lemma aseg_E : forall s msF mo regs mem (pp : word) (A : Z) K,
    abase_regs regs pp -> getr regs 10 = Z_to_bv 64 A -> (0 < A < 2 ^ 64)%Z -> getr regs 21 = Z_to_bv 64 0x10000 ->
    stk_ok RSEGS mem (Z_to_bv 64 (bv_unsigned sp0 - 128)) MSTK -> aro_none mem -> arelro_none mem ->
    (forall regs' mem' msF' mo',
        as_VIS H s msF' = mkst regs' (Z_to_bv 64 0xbe9ac) mem' rom -> as_AKREL H s (mkCfg msF' mo') -> same_but_materialized mo mo' ->
        an_regs regs' pp A 0 0x10000 ->
        frame_mod mem mem' (regL_w sp0) -> stk_ok RSEGS mem' (Z_to_bv 64 (bv_unsigned sp0 - 128)) MSTK ->
        realizes asegs (mkCfg msF' mo') K) ->
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xbe974) mem rom -> as_AKREL H s (mkCfg msF mo) ->
    realizes asegs (mkCfg msF mo) K.
