  Definition ag_regs : ltac2:(zQ "40!ig9!kke!iie!iqa>4regs@2$3@1$0#5@1$2@1$0#k0>2pp@1$2@1$0#k0>1A$1>3len$1P") := ltac2:(zQ "c0!ig9!iie!lh8!kk8!pf!lhc!li4!lia!ki2!kke!iqa!lsc\4regs@2$a@1$0#5@1$1@1$0#k0\2pp@1$1@1$0#k0\1A$9\3len$9@2$3@2$b^4^3@2$3@3$4@1$1@1$0#k0@2$5^4@3$6@1$0#5+9Kv$2@2$7@1$0#5+9@2$8@1$0#k0^2@2$3@3$4@1$1@1$0#k0@2$5^4@3$6@1$0#5+h3Kv$2@2$7@1$0#5+h3@2$8@1$0#k0^1@2$3@3$4@1$1@1$0#k0@2$5^4@3$6@1$0#5+h5Kv$2@2$7@1$0#5+h5@2$8@1$0#k0^1@3$4@1$1@1$0#k0@2$5^4@3$6@1$0#5+h7Kv$2@2$7@1$0#5+h7@2$8@1$0#k0^2").

  (* [comment removed for export] *)
  Lemma aseg_Mb : forall s msF mo regs mem (pp : word) (A len cap n : Z) K,
    am_regs regs pp A len cap n -> (0 <= len)%Z -> (0 <= n)%Z -> (0 <= cap < 2 ^ 63)%Z -> (len + n = cap)%Z ->
    stk_ok RSEGS mem (Z_to_bv 64 (bv_unsigned sp0 - 128)) MSTK -> aro_none mem -> arelro_none mem ->
    (forall regs' mem' msF' mo',
        as_VIS H s msF' = mkst regs' (Z_to_bv 64 0xbe9b4) mem' rom -> as_AKREL H s (mkCfg msF' mo') -> same_but_materialized mo mo' ->
        ag_regs regs' pp A cap ->
        frame_mod mem mem' (regL_w sp0) -> stk_ok RSEGS mem' (Z_to_bv 64 (bv_unsigned sp0 - 128)) MSTK ->
        realizes asegs (mkCfg msF' mo') K) ->
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xbe9a0) mem rom -> as_AKREL H s (mkCfg msF mo) ->
